package net.officefloor.hq.app;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/clients/projects?clientId=&lt;id&gt; — the projects of one client, in id order, each
 * carrying its client's NAME so the row reuses the same {@link ProjectView} shape the projects
 * list renders. Scoped to a client (the client detail page lists ITS projects), so the client id
 * arrives as a query parameter. Wired by officefloor/rest/api/clients/projects.GET.yml.
 */
public class ListClientProjects {

    public void service(@RequestParam("clientId") String clientId,
            ProjectRepository projects, ClientRepository clients,
            ObjectResponse<List<ProjectView>> response) {
        Long id = Long.valueOf(clientId);
        String clientName = clients.findById(id).map(Client::getName).orElse("");
        List<ProjectView> view = projects.findByClientIdOrderByIdAsc(id).stream()
                .map(p -> ProjectView.of(p, clientName))
                .toList();
        response.send(view);
    }
}
=== ProjectView.java ===
package net.officefloor.hq.app;

/**
 * What the API exposes for a project: the shape the front-end renders into the projects table. The
 * cross-entity join lives here — the project carries its client's NAME (not just the id) so the list
 * can show the client without a second lookup.
 */
public record ProjectView(Long id, String name, Long clientId, String clientName) {

    public static ProjectView of(Project project, String clientName) {
        return new ProjectView(project.getId(), project.getName(), project.getClientId(), clientName);
    }
}
=== Audit.java ===
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI (DESIGN.md §3, docs/SUT_CONTRACT.md §4). The file path + one-record-per-line
 * format is a declared, stable contract, like data-testid: features may be rewritten as long as
 * they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Checkpoints assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

